import os, tempfile; os.chdir(tempfile.mkdtemp())
with open('data.txt', 'w', encoding='utf-8') as file_obj:
    print(file_obj.write('abc'), file_obj.closed)
print(file_obj.closed)
try:
    with open('data.txt', 'w', encoding='utf-8') as g: raise RuntimeError('boom')
except RuntimeError:
    print(g.closed)

import os, tempfile; os.chdir(tempfile.mkdtemp())
from pathlib import Path
log = Path('log.txt')
for mode, text in (('w', 'A\n'), ('a', 'B\n'), ('a', 'C\n'), ('w', 'D\n')):
    with open(log, mode, encoding='utf-8') as f:
        f.write(text)
    print(mode, repr(log.read_text()))
try: open(log, 'x')
except FileExistsError: print('x refuses: the file exists')

import os, tempfile; os.chdir(tempfile.mkdtemp())
from pathlib import Path
Path('a.txt').write_text('café', encoding='utf-8')
print(open('a.txt', encoding='utf-8').read())
print(open('a.txt', encoding='ascii', errors='replace').read())
try: print(open('a.txt', encoding='ascii').read())
except UnicodeDecodeError: print('ascii cannot read the byte 0xc3')
for enc in ('utf-8', 'utf-16-le', 'latin-1'):
    print(enc, len('café'.encode(enc)))

import os, re, tempfile; os.chdir(tempfile.mkdtemp())
from pathlib import Path
put = lambda f, t: Path(f).write_text(t, encoding='utf-8')
put('a.txt', 'spam and eggs\nbacon alone\nSPAM again\n')
put('b.txt', 'nothing here\nspam, glorious spam\n')
put('notes.csv', 'spam,1\n')
for p in sorted(Path('.').glob('*.txt')):
    lines = p.read_text(encoding='utf-8').splitlines()
    for n, line in enumerate(lines, 1):
        if re.search('spam', line): print(f'{p.name}:{n}: {line}')
